  W("fitting room", "/ˈfɪtɪŋ ruːm/", "noun", "примірочна", "Where is the fitting room?", "Де примірочна?"),
  W("bigger", "/ˈbɪɡə/", A, "більший", "A bigger one, please.", "Більший, будь ласка."),
